const r = await api.get("/customers", {});
const items = r.items || [];
if (items.length === 0) return { count: r.count, note: "목록 없음" };
let best = items[0];
for (const c of items) if (c.points > best.points) best = c;
const ties = items.filter(c => c.points === best.points).map(c => c.id);
return { total: items.length, count: r.count, maxPoints: best.points, ids: ties };

